  7	import { ipcBridge } from '@/common';
  8	import { CUSTOM_AVATAR_IMAGE_MAP } from '@/renderer/pages/guid/constants';
  9	import { getAgentLogo } from '@/renderer/utils/model/agentLogo';
 10	import { emitter } from '@/renderer/utils/emitter';
 11	import { cleanupSiderTooltips } from '@/renderer/utils/ui/siderTooltip';
 12	import { updateWorkspaceTime } from '@/renderer/utils/workspace/workspaceHistory';
 13	import { Dropdown, Menu, Message, Tag } from '@arco-design/web-react';
 14	import { Close, Plus, Robot } from '@icon-park/react';
 15	import React, { useCallback, useEffect, useRef, useState } from 'react';
 16	import { useTranslation } from 'react-i18next';
 17	import { useNavigate } from 'react-router-dom';
 18	import { useConversationTabs } from '../hooks/ConversationTabsContext';
 19	import { useConversationAgents } from '../hooks/useConversationAgents';
 20	import { applyDefaultConversationName } from '../utils/newConversationName';
 21	import { buildCliAgentParams, buildPresetAssistantParams } from '../utils/createConversationParams';
 22	import { useLayoutContext } from '@/renderer/hooks/context/LayoutContext';
 23	import { iconColors } from '@/renderer/styles/colors';
 24
 25	const TAB_OVERFLOW_THRESHOLD = 10;
 26
 27	interface TabFadeState {
 28	  left: boolean;
 29	  right: boolean;
 30	}
 31
 32	interface ConversationTabViewProps {
 33	  tabId: string;
 34	  tabName: string;
 35	  isActive: boolean;
 36	  isMobile: boolean;
 37	  contextMenu: React.ReactNode;
 38	  onSwitch: (tabId: string) => void;
 39	  onClose: (tabId: string) => void;
 40	}
 41
 42	const ConversationTabView: React.FC<ConversationTabViewProps> = ({
 43	  tabId,
 44	  tabName,
 45	  isActive,
 46	  isMobile,
 47	  contextMenu,
 48	  onSwitch,
 49	  onClose,
 50	}) => {
 51	  const tabClassName = `flex items-center gap-8px px-12px h-full max-w-240px cursor-pointer transition-all duration-200 shrink-0 border-r border-[color:var(--border-base)] ${isActive ? 'bg-1 text-[color:var(--color-text-1)] font-medium' : 'bg-2 text-[color:var(--color-text-3)] hover:text-[color:var(--color-text-2)] border-b border-[color:var(--border-base)]'}`;
 52
 53	  return (
 54	    <Dropdown droplist={contextMenu} trigger='contextMenu' position='bl'>
 55	      <div
 56	        className={tabClassName}
 57	        style={{ borderRight: '1px solid var(--border-base)' }}
 58	        onClick={() => onSwitch(tabId)}
 59	        title={isMobile ? undefined : tabName}
 60	      >
 61	        <span className='text-15px whitespace-nowrap overflow-hidden text-ellipsis select-none flex-1'>{tabName}</span>
 62	        <Close
 63	          theme='outline'
 64	          size='14'
 65	          fill={iconColors.secondary}
 66	          className='shrink-0 transition-all duration-200 hover:fill-[rgb(var(--danger-6))]'
 67	          onClick={(event) => {
 68	            event.stopPropagation();
 69	            onClose(tabId);
 70	          }}
 71	        />
 72	      </div>
 73	    </Dropdown>
 74	  );
 75	};
 76
 77	interface CreateConversationTriggerProps {
 78	  disabled: boolean;
 79	  title: string;
 80	  menu: React.ReactNode;
 81	}
 82
 83	const CreateConversationTrigger: React.FC<CreateConversationTriggerProps> = ({ disabled, title, menu }) => (
 84	  <Dropdown droplist={menu} trigger='click' position='bl' disabled={disabled}>
 85	    <div
 86	      className={`flex items-center justify-center w-40px h-40px shrink-0 transition-colors duration-200 ${disabled ? 'cursor-not-allowed opacity-50' : 'cursor-pointer hover:bg-[var(--fill-2)]'}`}
 87	      style={{ borderLeft: '1px solid var(--border-base)' }}
 88	      title={title}
 89	    >
 90	      <Plus theme='outline' size='16' fill={iconColors.primary} strokeWidth={3} />
 91	    </div>
 92	  </Dropdown>
 93	);
 94
 95	/**
 96	 * 会话 Tabs 栏组件
 97	 * Conversation tabs bar component
 98	 *
 99	 * 显示所有打开的会话 tabs，支持切换、关闭和新建会话
100	 * Displays all open conversation tabs, supports switching, closing, and creating new conversations
101	 */
102	const ConversationTabs: React.FC = () => {
103	  const layout = useLayoutContext();
104	  const isMobile = layout?.isMobile ?? false;
105	  const {
106	    openTabs,
107	    activeTabId,
108	    switchTab,
109	    closeTab,
110	    closeAllTabs,
111	    closeTabsToLeft,
112	    closeTabsToRight,
113	    closeOtherTabs,
114	    openTab,
115	  } = useConversationTabs();
116	  const navigate = useNavigate();
117	  const { t, i18n } = useTranslation();
118	  const tabsContainerRef = useRef<HTMLDivElement>(null);
119	  const [tabFadeState, setTabFadeState] = useState<TabFadeState>({ left: false, right: false });
120
121	  const { cliAgents, presetAssistants, isLoading } = useConversationAgents();
122	  const defaultConversationName = t('conversation.welcome.newConversation');
123	  const isCreatingRef = useRef(false);
124
125	  // 更新 Tab 溢出状态
126	  const updateTabOverflow = useCallback(() => {
127	    const container = tabsContainerRef.current;
128	    if (!container) return;
129
130	    const { scrollLeft, scrollWidth, clientWidth } = container;
131	    const hasOverflow = scrollWidth > clientWidth + 1;
132
133	    const nextState: TabFadeState = {
134	      left: hasOverflow && scrollLeft > TAB_OVERFLOW_THRESHOLD,
135	      right: hasOverflow && scrollLeft + clientWidth < scrollWidth - TAB_OVERFLOW_THRESHOLD,
136	    };
137
138	    setTabFadeState((prev) => {
139	      if (prev.left === nextState.left && prev.right === nextState.right) return prev;
140	      return nextState;
141	    });
142	  }, []);
143
144	  // 当 tabs 变化时更新溢出状态
145	  useEffect(() => {
146	    updateTabOverflow();
147	  }, [updateTabOverflow, openTabs.length]);
148
149	  // 监听滚动和窗口大小变化
150	  useEffect(() => {
151	    const container = tabsContainerRef.current;
152	    if (!container) return;
153
154	    const handleScroll = () => updateTabOverflow();
155	    container.addEventListener('scroll', handleScroll, { passive: true });
156	    window.addEventListener('resize', updateTabOverflow);
157
158	    let resizeObserver: ResizeObserver | null = null;
159	    if (typeof ResizeObserver !== 'undefined') {
160	      resizeObserver = new ResizeObserver(() => updateTabOverflow());
161	      resizeObserver.observe(container);
162	    }
163
164	    return () => {
165	      container.removeEventListener('scroll', handleScroll);
166	      window.removeEventListener('resize', updateTabOverflow);
167	      if (resizeObserver) {
168	        resizeObserver.disconnect();
169	      }
170	    };
171	  }, [updateTabOverflow]);
172
173	  // 切换 tab 并导航
174	  const handleSwitchTab = useCallback(
175	    (tabId: string) => {
176	      cleanupSiderTooltips();
177	      switchTab(tabId);
178	      void navigate(`/conversation/${tabId}`);
179	    },
180	    [switchTab, navigate]
181	  );
182
183	  // 关闭 tab
184	  const handleCloseTab = useCallback(
185	    (tabId: string) => {
186	      cleanupSiderTooltips();
187	      closeTab(tabId);
188	      // 如果关闭的是当前 tab，导航将由 context 自动处理（切换到最后一个）
189	      // 如果没有 tab 了，导航到欢迎页
190	      if (openTabs.length === 1 && tabId === activeTabId) {
191	        void navigate('/guid');
192	      }
193	    },
194	    [closeTab, openTabs.length, activeTabId, navigate]
195	  );
196
197	  // 创建新会话 - 通过下拉菜单选择 Agent/助手后创建
198	  const handleCreateConversation = useCallback(
199	    async (key: string) => {
200	      if (isCreatingRef.current) return;
201	      isCreatingRef.current = true;
202
203	      const currentTab = openTabs.find((tab) => tab.id === activeTabId);
204	      if (!currentTab?.workspace) {
205	        isCreatingRef.current = false;
206	        void navigate('/guid');
207	        return;
208	      }
209
210	      const workspace = currentTab.workspace;
211
212	      try {
213	        // [BUG-3] Build params inside try block: getDefaultGeminiModel() may throw if no model configured
214	        let params;
215
216	        if (key.startsWith('cli:')) {
217	          const backend = key.slice(4);
218	          // [BUG-6] Null check: find() may return undefined
219	          const agent = cliAgents.find((a) => a.backend === backend);
220	          if (!agent) {
221	            Message.error(t('conversation.createFailed'));
222	            return;
223	          }
224	          params = await buildCliAgentParams(agent, workspace);
225	        } else if (key.startsWith('preset:')) {
226	          const assistantId = key.slice(7);
227	          // [BUG-6] Null check: find() may return undefined
228	          const agent = presetAssistants.find((a) => a.customAgentId === assistantId);
229	          if (!agent) {
230	            Message.error(t('conversation.createFailed'));
231	            return;
232	          }
233	          params = await buildPresetAssistantParams(agent, workspace, i18n.language);
234	        } else {
235	          return;
236	        }
237
238	        // Use conversation.create (calls ConversationService) not createWithConversation (direct DB insert)
239	        const newConversation = await ipcBridge.conversation.create.invoke(
240	          applyDefaultConversationName(params, defaultConversationName)
241	        );
242
243	        // [BUG-5] Order matters: closeAllTabs() must come before openTab() to prevent append behavior
244	        closeAllTabs();
245	        updateWorkspaceTime(workspace);
246	        openTab(newConversation);
247	        void navigate(`/conversation/${newConversation.id}`);
248	        emitter.emit('chat.history.refresh');
249	      } catch (error) {
250	        // [BUG-3] Unified catch: handles both param building errors (getDefaultGeminiModel) and IPC errors
251	        console.error('Failed to create conversation:', error);
252	        Message.error(t('conversation.createFailed'));
253	      } finally {
254	        isCreatingRef.current = false;
255	      }
256	    },
257	    [
258	      navigate,
259	      openTabs,
260	      activeTabId,
261	      cliAgents,
262	      presetAssistants,
263	      closeAllTabs,
264	      openTab,
265	      t,
266	      i18n.language,
267	      defaultConversationName,
268	    ]
269	  );
270
271	  // 渲染 Agent 下拉菜单
272	  const renderAgentDropdownMenu = useCallback(() => {
273	    return (
274	      <Menu onClickMenuItem={(key) => void handleCreateConversation(key)}>
275	        {cliAgents.length > 0 && (
276	          <Menu.ItemGroup title={t('conversation.dropdown.cliAgents')}>
277	            {cliAgents.map((agent) => {
278	              const logo = getAgentLogo(agent.backend);
279	              return (
280	                <Menu.Item key={`cli:${agent.backend}`}>
281	                  <div className='flex items-center gap-8px'>
282	                    {logo ? (
283	                      <img src={logo} alt={agent.name} style={{ width: 16, height: 16, objectFit: 'contain' }} />
284	                    ) : (
285	                      <Robot size='16' />
286	                    )}
287	                    <span>{agent.name}</span>
288	                    {agent.isExtension && (
289	                      <Tag size='small' color='arcoblue'>
290	                        ext
291	                      </Tag>
292	                    )}
293	                  </div>
294	                </Menu.Item>
295	              );
296	            })}
297	          </Menu.ItemGroup>
298	        )}
299	        {presetAssistants.length > 0 && (
300	          <Menu.ItemGroup title={t('conversation.dropdown.presetAssistants')}>
301	            {presetAssistants.map((agent) => {
302	              const avatarImage = agent.avatar ? CUSTOM_AVATAR_IMAGE_MAP[agent.avatar] : undefined;
303	              const isEmoji = agent.avatar && !avatarImage && !agent.avatar.endsWith('.svg');
304	              return (
305	                <Menu.Item key={`preset:${agent.customAgentId}`}>
306	                  <div className='flex items-center gap-8px'>
307	                    {avatarImage ? (
308	                      <img src={avatarImage} alt={agent.name} style={{ width: 16, height: 16, objectFit: 'contain' }} />
309	                    ) : isEmoji ? (
310	                      <span style={{ fontSize: 14, lineHeight: '16px' }}>{agent.avatar}</span>
311	                    ) : (
312	                      <Robot size='16' />
313	                    )}
314	                    <span>{agent.name}</span>
315	                  </div>
316	                </Menu.Item>
317	              );
318	            })}
319	          </Menu.ItemGroup>
320	        )}
321	      </Menu>
322	    );
323	  }, [cliAgents, presetAssistants, handleCreateConversation, t]);
324
325	  // 生成右键菜单内容
326	  const getContextMenu = useCallback(
327	    (tabId: string) => {
328	      const tabIndex = openTabs.findIndex((tab) => tab.id === tabId);
329	      const hasLeftTabs = tabIndex > 0;
330	      const hasRightTabs = tabIndex < openTabs.length - 1;
331	      const hasOtherTabs = openTabs.length > 1;
332
333	      return (
334	        <Menu
335	          onClickMenuItem={(key) => {
336	            switch (key) {
337	              case 'close-all':
338	                closeAllTabs();
339	                void navigate('/guid');
340	                break;
341	              case 'close-left':
342	                closeTabsToLeft(tabId);
343	                break;
344	              case 'close-right':
345	                closeTabsToRight(tabId);
346	                break;
347	              case 'close-others':
348	                closeOtherTabs(tabId);
349	                void navigate(`/conversation/${tabId}`);
350	                break;
351	            }
352	          }}
353	        >
354	          <Menu.Item key='close-others' disabled={!hasOtherTabs}>
355	            {t('conversation.tabs.closeOthers')}
356	          </Menu.Item>
357	          <Menu.Item key='close-left' disabled={!hasLeftTabs}>
358	            {t('conversation.tabs.closeLeft')}
359	          </Menu.Item>
360	          <Menu.Item key='close-right' disabled={!hasRightTabs}>
361	            {t('conversation.tabs.closeRight')}
362	          </Menu.Item>
363	          <Menu.Item key='close-all'>{t('conversation.tabs.closeAll')}</Menu.Item>
364	        </Menu>
365	      );
366	    },
367	    [openTabs, closeAllTabs, closeTabsToLeft, closeTabsToRight, closeOtherTabs, navigate, t]
368	  );
369
370	  const { left: showLeftFade, right: showRightFade } = tabFadeState;
371	  // 检查当前激活的 tab 是否在 openTabs 中
372	  // Check if current active tab is in openTabs
373	  const isActiveTabInList = openTabs.some((tab) => tab.id === activeTabId);
374
375	  // 如果没有打开的 tabs，或者当前激活的会话不在 tabs 中（说明切换到了非工作空间会话），不显示此组件
376	  // If no open tabs, or active conversation is not in tabs (switched to non-workspace chat), hide component
377	  if (openTabs.length === 0 || !isActiveTabInList) {
378	    return null;
379	  }
380
381	  const isDropdownDisabled = isLoading || (!cliAgents.length && !presetAssistants.length);
382
383	  return (
384	    <div className='relative shrink-0 bg-2 min-h-40px'>
385	      <div className='relative flex items-center h-40px w-full border-t border-x border-solid border-[color:var(--border-base)]'>
386	        {/* Tabs 滚动区域 */}
387	        <div
388	          ref={tabsContainerRef}
389	          className='flex items-center h-full flex-1 overflow-x-auto overflow-y-hidden [scrollbar-width:none] [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden'
390	        >
391	          {openTabs.map((tab) => (
392	            <ConversationTabView
393	              key={tab.id}
394	              tabId={tab.id}
395	              tabName={tab.name}
396	              isActive={tab.id === activeTabId}
397	              isMobile={isMobile}
398	              contextMenu={getContextMenu(tab.id)}
399	              onSwitch={handleSwitchTab}
400	              onClose={handleCloseTab}
401	            />
402	          ))}
403	        </div>
404
405	        {/* 新建会话按钮 - 点击显示 Agent 下拉选择 */}
406	        <CreateConversationTrigger
407	          disabled={isDropdownDisabled}
408	          title={t('conversation.workspace.createNewConversation')}
409	          menu={renderAgentDropdownMenu()}
410	        />
411
412	        {/* 左侧渐变指示器 */}
413	        {showLeftFade && (
414	          <div className='pointer-events-none absolute left-0 top-0 bottom-0 w-32px [background:linear-gradient(90deg,var(--bg-2)_0%,transparent_100%)]' />
415	        )}
416
417	        {/* 右侧渐变指示器 */}
418	        {showRightFade && (
419	          <div className='pointer-events-none absolute right-40px top-0 bottom-0 w-32px [background:linear-gradient(270deg,var(--bg-2)_0%,transparent_100%)]' />
420	        )}
421	      </div>
422	    </div>
423	  );
424	};
425
426	export default ConversationTabs;

